// Level B1 modules of work.html (format in assets/js/work.js). Original dialogues and questions.
SECTIONS.extend("work", "b1", { items: [
  { id: "places", t: { ar: "توصف أماكن وأحداث", en: "Describing places and events" },
    body: { ar: "توصف مكان وحدث بتفاصيل: **There will be…**، **It takes place in…**، والصفات قبل الأسماء **a large, bright room**.", en: "Describe a place and an event in detail: **There will be…**, **It takes place in…**, and adjectives before nouns **a large, bright room**." },
    d: [["Rana", "Are you joining the hackathon next month?", "هتشترك في الهاكاثون الشهر الجاي؟"],
        ["Leo", "I'd like to. Where does it take place?", "نفسي. هيتعمل فين؟"],
        ["Rana", "In the new innovation hub downtown. It's a large, bright building with a rooftop.", "في مركز الابتكار الجديد في وسط البلد. مبنى كبير ومنوّر وفيه روف."],
        ["Leo", "How long does it last?", "مدته قد إيه؟"],
        ["Rana", "Forty-eight hours. There will be mentors, free food and a demo stage.", "تمانية وأربعين ساعة. هيبقى فيه mentors وأكل ببلاش ومسرح للعروض."],
        ["Leo", "Sounds amazing. Let's form a team.", "شكله تحفة. يلا نعمل فريق."]],
    ph: [["Where does it take place?", "هيتعمل فين؟"], ["It's a large, bright building.", "مبنى كبير ومنوّر."], ["How long does it last?", "مدته قد إيه؟"], ["There will be mentors and free food.", "هيبقى فيه mentors وأكل ببلاش."]],
    q: [["f", "Where does it take ___?", "place", ["part", "space"], "take place = يحصل/يتعمل.", "«take place» = happen."],
        ["f", "There ___ be mentors and free food.", "will", ["are", "is going"], "There will be = هيبقى فيه.", "«There will be» for the future."],
        ["f", "It's a ___ building.", "large, bright", ["bright large,", "building large"], "الصفات بتيجي قبل الاسم.", "Adjectives come before the noun."],
        ["m", "الهاكاثون مدته قد إيه؟", "How long is the hackathon?", ["48 hours", "One week", "One day"], 0, "Forty-eight hours.", "«Forty-eight hours.»"],
        ["m", "How long does it last? بيسأل عن إيه؟", "What does «How long does it last?» ask about?", ["The duration", "The place", "The price"], 0, "last = يستمر، فالسؤال عن المدة.", "«last» = continue; it asks for the duration."]] },

  { id: "past-exp", t: { ar: "تحكي تجارب حصلت قبل كده", en: "Talking about past experiences" },
    body: { ar: "**Have you ever…?** للتجربة من غير وقت محدد، والماضي البسيط لما تقول إمتى: **Yes, I did it last year.**", en: "**Have you ever…?** for experience without a time, and the past simple when you say when: **Yes, I did it last year.**" },
    d: [["Hadi", "Have you ever debugged a memory leak?", "عمرك صلّحت memory leak؟"],
        ["Bella", "Yes, once. It was in a Node service last year.", "أيوه، مرة. كانت في خدمة Node السنة اللي فاتت."],
        ["Hadi", "How did you find it?", "لقيتيها إزاي؟"],
        ["Bella", "I took heap snapshots and compared them. A cache never deleted old items.", "أخدت heap snapshots وقارنتهم. كان فيه cache عمره ما بيمسح العناصر القديمة."],
        ["Hadi", "I've never done that. Could you show me sometime?", "عمري ما عملت كده. ممكن توريني في أي وقت؟"],
        ["Bella", "Sure, I've written a short guide about it.", "أكيد، كتبت دليل صغير عن الموضوع."]],
    ph: [["Have you ever…?", "عمرك…؟"], ["Yes, once. It was last year.", "أيوه، مرة. كانت السنة اللي فاتت."], ["I've never done that.", "عمري ما عملت كده."], ["How did you find it?", "لقيتها إزاي؟"]],
    q: [["f", "Have you ___ debugged a memory leak?", "ever", ["never", "yet"], "Have you ever…? = عمرك…؟", "«Have you ever…?» asks about experience."],
        ["f", "It ___ in a Node service last year.", "was", ["has been", "is"], "last year وقت محدد → ماضي بسيط.", "«last year» is a fixed time → past simple."],
        ["f", "I've never ___ that.", "done", ["did", "do"], "have + التصريف التالت: done.", "have + past participle: «done»."],
        ["m", "إيه سبب الـ leak؟", "What caused the leak?", ["A cache never deleted old items.", "A slow database", "A missing file"], 0, "A cache never deleted old items.", "«A cache never deleted old items.»"],
        ["m", "أنهي جملة صح؟", "Which sentence is correct?", ["I saw that bug yesterday.", "I have seen that bug yesterday.", "I have saw that bug."], 0, "yesterday وقت محدد → saw.", "«yesterday» needs the past simple."]] },

  { id: "past-act", t: { ar: "تحكي أنشطة عملتها", en: "Talking about past activities" },
    body: { ar: "الماضي المستمر للخلفية والماضي البسيط للحدث: **We were testing the app when the server crashed.**", en: "Past continuous for the background and past simple for the event: **We were testing the app when the server crashed.**" },
    d: [["Eva", "Did you read the latest user feedback?", "قريت آخر feedback من المستخدمين؟"],
        ["Malik", "Yes. Many users were trying to pay when the page froze.", "أيوه. ناس كتير كانوا بيحاولوا يدفعوا لما الصفحة وقفت."],
        ["Eva", "When did that happen?", "ده حصل إمتى؟"],
        ["Malik", "On Saturday night. We were deploying a new version at the same time.", "سبت بالليل. كنا بننشر نسخة جديدة في نفس الوقت."],
        ["Eva", "So the deploy caused it?", "يعني النشر هو السبب؟"],
        ["Malik", "Probably. While the servers were restarting, the payment service lost connection.", "غالبًا. وإحنا السيرفرات بتعمل restart، خدمة الدفع فقدت الاتصال."]],
    ph: [["Users were trying to pay when the page froze.", "المستخدمين كانوا بيحاولوا يدفعوا لما الصفحة وقفت."], ["We were deploying at the same time.", "كنا بننشر في نفس الوقت."], ["While the servers were restarting, …", "وإحنا السيرفرات بتعمل restart، …"], ["When did that happen?", "ده حصل إمتى؟"]],
    q: [["f", "Users were trying to pay when the page ___.", "froze", ["was freezing", "freezes"], "الحدث المفاجئ بالماضي البسيط.", "The sudden event uses the past simple."],
        ["f", "We ___ deploying a new version.", "were", ["was", "are"], "we → were.", "«we» → «were»."],
        ["f", "___ the servers were restarting, the service lost connection.", "While", ["During", "When it"], "While + جملة مستمرة.", "«While» + a continuous clause."],
        ["m", "الصفحة وقفت إمتى؟", "When did the page freeze?", ["On Saturday night", "On Monday morning", "Yesterday afternoon"], 0, "On Saturday night.", "«On Saturday night.»"],
        ["m", "الماضي المستمر بيوصف إيه؟", "What does the past continuous describe?", ["An action in progress at a past moment", "A finished short action", "A future plan"], 0, "حدث كان شغال في لحظة في الماضي.", "Something in progress at a past moment."]] },

  { id: "present-perfect", t: { ar: "المضارع التام وإنت بتتكلم عن الـ accessibility", en: "Present perfect while talking about accessibility" },
    body: { ar: "**We have added / We haven't tested yet / since / for** وإنت بتتكلم عن قارئ الشاشة والـ alt text والتباين.", en: "**We have added / We haven't tested yet / since / for** while talking about screen readers, alt text and contrast." },
    d: [["Ines", "What have you done for accessibility this sprint?", "عملتوا إيه للـ accessibility في الـ sprint ده؟"],
        ["Victor", "We've added alt text to all product images.", "ضفنا alt text لكل صور المنتجات."],
        ["Ines", "Have you tested the site with a screen reader?", "اختبرتوا الموقع بقارئ شاشة؟"],
        ["Victor", "Not yet. We've only checked the color contrast.", "لسه. فحصنا تباين الألوان بس."],
        ["Ines", "The forms have had problems since the redesign. Labels are missing.", "الفورمات فيها مشاكل من ساعة الـ redesign. الـ labels ناقصة."],
        ["Victor", "Right. I've just created a ticket for that.", "صح. لسه عامل تذكرة للموضوع ده."]],
    ph: [["We've added alt text to all images.", "ضفنا alt text لكل الصور."], ["Have you tested it with a screen reader?", "اختبرته بقارئ شاشة؟"], ["since the redesign", "من ساعة الـ redesign"], ["I've just created a ticket.", "لسه عامل تذكرة."]],
    q: [["f", "We've ___ alt text to all images.", "added", ["add", "adding"], "have + added.", "have + past participle."],
        ["f", "The forms have had problems ___ the redesign.", "since", ["for", "from"], "since + نقطة بداية.", "«since» + a starting point."],
        ["f", "I've ___ created a ticket.", "just", ["yet", "ever"], "just = لسه حالًا.", "«just» = a moment ago."],
        ["m", "إيه اللي لسه مااختبروهوش؟", "What haven't they tested yet?", ["The screen reader", "The color contrast", "The images"], 0, "Not yet. We've only checked the color contrast.", "The screen reader test is not done."],
        ["m", "alt text فايدته إيه؟", "What is alt text for?", ["Describing images for screen readers", "Making images load faster", "Changing colors"], 0, "قارئ الشاشة بيقراه بدل الصورة.", "Screen readers read it instead of the image."]] },

  { id: "future-plan", t: { ar: "تخطط لأحداث جاية", en: "Planning future events" },
    body: { ar: "المضارع المستمر للمواعيد المتفق عليها **We're meeting on Monday**، و**going to** للنية، و**will** للتوقع.", en: "Present continuous for fixed arrangements **We're meeting on Monday**, **going to** for intentions, and **will** for predictions." },
    d: [["Fady", "We're running scheduled maintenance on Sunday night to protect the site from DoS attacks.", "هنعمل صيانة مجدولة ليلة الحد عشان نحمي الموقع من هجمات DoS."],
        ["Lea", "What time are you starting?", "هتبدأوا الساعة كام؟"],
        ["Fady", "At midnight. We're going to add rate limiting and a new firewall rule.", "الساعة 12. هنضيف rate limiting وقاعدة firewall جديدة."],
        ["Lea", "Will users notice anything?", "المستخدمين هيحسوا بحاجة؟"],
        ["Fady", "I think the site will be down for about ten minutes.", "أعتقد الموقع هيقف حوالي عشر دقايق."],
        ["Lea", "OK. I'm sending a notice to customers tomorrow.", "تمام. هبعت إشعار للعملاء بكره."]],
    ph: [["We're running maintenance on Sunday night.", "هنعمل صيانة ليلة الحد."], ["We're going to add rate limiting.", "هنضيف rate limiting."], ["Will users notice anything?", "المستخدمين هيحسوا بحاجة؟"], ["The site will be down for ten minutes.", "الموقع هيقف عشر دقايق."]],
    q: [["f", "We ___ running maintenance on Sunday.", "are", ["will", "do"], "موعد متفق عليه → are + ing.", "A fixed arrangement → are + -ing."],
        ["f", "I think the site ___ be down for ten minutes.", "will", ["is going", "is"], "توقع بعد I think → will.", "A prediction after «I think» → «will»."],
        ["f", "We're going to ___ a new firewall rule.", "add", ["adding", "added"], "going to + فعل في أصله.", "«going to» + base verb."],
        ["m", "ليه الصيانة؟", "Why is there maintenance?", ["To protect the site from DoS attacks", "To change the design", "To delete users"], 0, "to protect the site from DoS attacks.", "«…from DoS attacks.»"],
        ["m", "لي هتعمل إيه بكره؟", "What will Lea do tomorrow?", ["Send a notice to customers", "Run the maintenance", "Add a firewall rule"], 0, "I'm sending a notice to customers tomorrow.", "She is sending a notice."]] },

  { id: "future-cont", t: { ar: "المستقبل المستمر وإنت بتوصف أفعال", en: "Future continuous for actions" },
    body: { ar: "**will be + ing** لحاجة هتكون شغالة في وقت معين في المستقبل: **At 3 pm I'll be presenting.**", en: "**will be + -ing** for something in progress at a future time: **At 3 pm I'll be presenting.**" },
    d: [["Kim", "Can I call you tomorrow at ten?", "أكلمك بكره الساعة عشرة؟"],
        ["Rami", "At ten I'll be migrating the database, so I won't be online.", "الساعة عشرة هكون بنقل قاعدة البيانات، فمش هبقى أونلاين."],
        ["Kim", "How long will you be working on it?", "هتفضل شغال عليها قد إيه؟"],
        ["Rami", "Until about noon. After that, I'll be monitoring the logs.", "لحد الضهر تقريبًا. بعدها هبقى براقب الـ logs."],
        ["Kim", "OK, I'll message you instead.", "تمام، هبعتلك رسالة بدل كده."]],
    ph: [["At ten I'll be migrating the database.", "الساعة عشرة هكون بنقل قاعدة البيانات."], ["I won't be online.", "مش هبقى أونلاين."], ["I'll be monitoring the logs.", "هبقى براقب الـ logs."], ["I'll message you instead.", "هبعتلك رسالة بدل كده."]],
    q: [["f", "At ten I'll ___ migrating the database.", "be", ["being", "been"], "will be + ing.", "will be + -ing."],
        ["f", "How long will you be ___ on it?", "working", ["work", "worked"], "will be + ing.", "will be + -ing."],
        ["f", "I ___ be online.", "won't", ["don't", "am not will"], "won't = will not.", "«won't» = will not."],
        ["m", "رامي هيعمل إيه بعد الضهر؟", "What will Rami be doing after noon?", ["Monitoring the logs", "Migrating the database", "Sleeping"], 0, "I'll be monitoring the logs.", "«I'll be monitoring the logs.»"],
        ["m", "المستقبل المستمر بيوصف إيه؟", "What does the future continuous describe?", ["An action in progress at a future time", "A finished past action", "A habit"], 0, "حاجة هتكون شغالة في لحظة جاية.", "Something in progress at a future moment."]] },

  { id: "conditionals", t: { ar: "الجمل الشرطية", en: "Using conditionals" },
    body: { ar: "الشرط الأول للحاجة الممكنة: **If it doesn't boot, check the cable.** والتاني للخيال: **If I had more time, I would rewrite it.**", en: "First conditional for real possibilities: **If it doesn't boot, check the cable.** Second for imagined ones: **If I had more time, I would rewrite it.**" },
    d: [["Support", "If the computer doesn't boot, check the power cable first.", "لو الكمبيوتر ماشتغلش، بص على كابل الكهربا الأول."],
        ["User", "I checked it. It's fine.", "بصيت عليه. كويس."],
        ["Support", "If you see a black screen, press F2 to open the setup.", "لو شفت شاشة سودا، دوس F2 عشان تفتح الإعدادات."],
        ["User", "And if that doesn't work?", "ولو ماجابش نتيجة؟"],
        ["Support", "Then we'll replace the disk. If I were you, I would back up your files today.", "ساعتها هنغيّر الهارد. لو كنت مكانك كنت عملت backup لملفاتك النهارده."]],
    ph: [["If it doesn't boot, check the cable.", "لو ماشتغلش، بص على الكابل."], ["If you see a black screen, press F2.", "لو شفت شاشة سودا، دوس F2."], ["If I were you, I would back up your files.", "لو كنت مكانك كنت عملت backup لملفاتك."], ["Then we'll replace the disk.", "ساعتها هنغيّر الهارد."]],
    q: [["f", "If the computer doesn't boot, ___ the cable.", "check", ["checked", "would checking"], "الشرط الأول: if + مضارع، والجواب أمر أو will.", "First conditional: if + present, then an imperative or will."],
        ["f", "If I ___ you, I would back up the files.", "were", ["am", "will be"], "If I were you تركيبة النصيحة.", "«If I were you» gives advice."],
        ["f", "If I had more time, I ___ rewrite it.", "would", ["will", "am"], "الشرط التاني: had … would.", "Second conditional: had … would."],
        ["m", "أول حاجة الدعم الفني طلبها؟", "What does support ask to check first?", ["The power cable", "The disk", "The screen"], 0, "check the power cable first.", "«check the power cable first»."],
        ["m", "أنهي جملة صح؟", "Which sentence is correct?", ["If it rains, we will stay inside.", "If it will rain, we stay inside.", "If it rained, we will stay."], 0, "if + مضارع، will في الجواب.", "if + present, «will» in the result."]] },

  { id: "feedback", t: { ar: "تدّي وتاخد feedback", en: "Sharing feedback" },
    body: { ar: "Feedback مفيد ومحترم: تبدأ بحاجة كويسة، وتقول اللي محتاج يتحسن بأمثلة، وتقترح خطوة. **One thing that could be better is…**", en: "Useful, respectful feedback: start with something good, say what needs work with examples, and suggest a step. **One thing that could be better is…**" },
    d: [["Manager", "Thanks for meeting me for your performance review.", "شكرًا إنك جيت لمراجعة الأداء."],
        ["Nada", "Of course.", "أكيد."],
        ["Manager", "Your code quality has been excellent this quarter. The tests you wrote saved us twice.", "جودة الكود بتاعك كانت ممتازة الربع ده. الاختبارات اللي كتبتيها أنقذتنا مرتين."],
        ["Manager", "One thing that could be better is communication. Two tasks were late and we heard about it on the deadline.", "حاجة ممكن تبقى أحسن هي التواصل. مهمتين اتأخروا وعرفنا يوم الـ deadline."],
        ["Nada", "That's fair. I'll flag delays as soon as I see them.", "عندك حق. هبلّغ عن أي تأخير أول ما أشوفه."],
        ["Manager", "Great. How can I support you better?", "عظيم. أقدر أدعمك أحسن إزاي؟"]],
    ph: [["Your code quality has been excellent.", "جودة الكود بتاعك كانت ممتازة."], ["One thing that could be better is…", "حاجة ممكن تبقى أحسن هي…"], ["That's fair.", "عندك حق / ده منطقي."], ["How can I support you better?", "أقدر أدعمك أحسن إزاي؟"]],
    q: [["f", "One thing that could be ___ is communication.", "better", ["good", "best"], "could be better = ممكن تبقى أحسن.", "«could be better» = could improve."],
        ["f", "I'll flag delays as ___ as I see them.", "soon", ["fast", "quick"], "as soon as = أول ما.", "«as soon as» = immediately when."],
        ["f", "How can I ___ you better?", "support", ["supporting", "supports"], "can + فعل في أصله.", "«can» + base verb."],
        ["m", "المدير بدأ بإيه؟", "How did the manager start?", ["With something positive", "With a complaint", "With a joke"], 0, "بدأ بجودة الكود والاختبارات.", "He praised the code quality and tests."],
        ["m", "إيه اللي محتاج يتحسن؟", "What needs to improve?", ["Communication about delays", "Code quality", "Tests"], 0, "communication.", "Communication about delays."]] },

  { id: "opinion", t: { ar: "تقول رأيك", en: "Sharing your opinion" },
    body: { ar: "رأي بأسباب: **From my point of view…**، **The main reason is…**، **On the other hand…**.", en: "An opinion with reasons: **From my point of view…**, **The main reason is…**, **On the other hand…**." },
    d: [["Sam", "Which language should we choose for the new service?", "نختار أنهي لغة للخدمة الجديدة؟"],
        ["Yara", "From my point of view, Go is the best choice. The main reason is performance.", "من وجهة نظري Go أحسن اختيار. السبب الأساسي السرعة."],
        ["Sam", "On the other hand, most of the team knows Python better.", "من ناحية تانية، معظم الفريق عارف Python أكتر."],
        ["Yara", "That's true. Personally, I think we can learn Go in a few weeks.", "ده صح. شخصيًا أعتقد نقدر نتعلم Go في كام أسبوع."],
        ["Sam", "Maybe. As far as I know, the deadline is very close, though.", "ممكن. بس على حد علمي الـ deadline قريب أوي."]],
    ph: [["From my point of view, …", "من وجهة نظري، …"], ["The main reason is performance.", "السبب الأساسي السرعة."], ["On the other hand, …", "من ناحية تانية، …"], ["As far as I know, …", "على حد علمي، …"]],
    q: [["f", "From my point of ___, Go is the best choice.", "view", ["see", "look"], "From my point of view تركيبة ثابتة.", "«From my point of view» is fixed."],
        ["f", "On the other ___, the team knows Python.", "hand", ["side", "way"], "On the other hand = من ناحية تانية.", "«On the other hand» introduces a contrast."],
        ["f", "As far as I ___, the deadline is close.", "know", ["knew it", "known"], "As far as I know = على حد علمي.", "«As far as I know» = to my knowledge."],
        ["m", "ليه يارا عايزة Go؟", "Why does Yara want Go?", ["Performance", "The team knows it", "It is new"], 0, "The main reason is performance.", "«The main reason is performance.»"],
        ["m", "إيه حجة سام ضد Go؟", "What is Sam's argument against Go?", ["The team knows Python better and time is short.", "Go is slow.", "Go is expensive."], 0, "most of the team knows Python better … the deadline is very close.", "Python skills and a close deadline."]] },

  { id: "agree-b1", t: { ar: "تعبّر عن الموافقة", en: "Expressing agreement" },
    body: { ar: "درجات الموافقة: **Absolutely / I couldn't agree more / I agree up to a point / That's a good point**.", en: "Degrees of agreement: **Absolutely / I couldn't agree more / I agree up to a point / That's a good point**." },
    d: [["Lead", "I suggest we release every two weeks instead of every month.", "بقترح ننشر كل أسبوعين بدل كل شهر."],
        ["Hana", "I couldn't agree more. Smaller releases are easier to test.", "موافقة تمامًا. الإصدارات الصغيرة أسهل في الاختبار."],
        ["Ziad", "That's a good point. And we'll get feedback faster.", "نقطة حلوة. وهنعرف رأي الناس أسرع."],
        ["Maya", "I agree up to a point, but we need better automation first.", "موافقة لحد ما، بس محتاجين أتمتة أحسن الأول."],
        ["Lead", "Absolutely. Let's automate the tests before we change anything.", "أكيد طبعًا. يلا نعمل أتمتة للاختبارات قبل ما نغيّر حاجة."]],
    ph: [["I couldn't agree more.", "موافق تمامًا."], ["That's a good point.", "نقطة حلوة."], ["I agree up to a point, but…", "موافق لحد ما، بس…"], ["Absolutely.", "أكيد طبعًا."]],
    q: [["f", "I couldn't agree ___.", "more", ["most", "less"], "I couldn't agree more = موافقة كاملة.", "«I couldn't agree more» = full agreement."],
        ["f", "I agree up to a ___, but we need automation.", "point", ["place", "level"], "up to a point = لحد ما.", "«up to a point» = partly."],
        ["f", "That's a good ___.", "point", ["idea of", "thought it"], "That's a good point تركيبة ثابتة.", "«That's a good point» is fixed."],
        ["m", "أنهي تعبير موافقة جزئية؟", "Which expresses partial agreement?", ["I agree up to a point.", "Absolutely.", "I couldn't agree more."], 0, "up to a point = لحد ما.", "«up to a point» means partly."],
        ["m", "قرروا يعملوا إيه الأول؟", "What will they do first?", ["Automate the tests", "Release next week", "Hire people"], 0, "Let's automate the tests before we change anything.", "Automate the tests first."]] },

  { id: "disagree", t: { ar: "تعبّر عن الاعتراض", en: "Expressing disagreement" },
    body: { ar: "اعتراض مهذب: **I'm not sure that's the best option**، **I see it differently**، **I'm afraid I disagree**، وتقترح بديل.", en: "Polite disagreement: **I'm not sure that's the best option**, **I see it differently**, **I'm afraid I disagree**, and offer an alternative." },
    d: [["PM", "Let's add the chat feature this sprint. Customers love it.", "يلا نضيف خاصية الشات الـ sprint ده. العملاء بيحبوها."],
        ["Dev", "I'm not sure that's the best option right now.", "مش متأكد إن ده أحسن اختيار دلوقتي."],
        ["PM", "Why not?", "ليه لأ؟"],
        ["Dev", "We still have twelve open bugs in checkout. I'm afraid I see it differently: payments come first.", "لسه عندنا 12 bug مفتوحين في الدفع. للأسف شايفها بشكل مختلف: الدفع الأول."],
        ["PM", "Hmm. What do you suggest?", "همم. تقترح إيه؟"],
        ["Dev", "Fix the bugs this sprint, and plan the chat for the next one.", "نصلّح الـ bugs الـ sprint ده، ونخطط للشات في اللي بعده."]],
    ph: [["I'm not sure that's the best option.", "مش متأكد إن ده أحسن اختيار."], ["I'm afraid I see it differently.", "للأسف شايفها بشكل مختلف."], ["What do you suggest?", "تقترح إيه؟"], ["…and plan it for the next one.", "…ونخطط له في اللي بعده."]],
    q: [["f", "I'm ___ I disagree.", "afraid", ["scared", "fear"], "I'm afraid هنا = للأسف (تلطيف).", "«I'm afraid» softens bad news."],
        ["f", "I see it ___.", "differently", ["different", "difference"], "بعد الفعل see بنستخدم الظرف differently.", "After the verb we use the adverb «differently»."],
        ["f", "I'm not sure that's the best ___.", "option", ["optional", "opt"], "option = اختيار.", "«option» = choice."],
        ["m", "المبرمج اقترح إيه؟", "What does the developer suggest?", ["Fix the bugs first, chat next sprint", "Add chat now", "Cancel the chat"], 0, "Fix the bugs this sprint, and plan the chat for the next one.", "Bugs now, chat next sprint."],
        ["m", "أنهي جملة اعتراض مهذب؟", "Which is a polite disagreement?", ["I'm not sure that's the best option.", "You are wrong.", "Bad idea."], 0, "بيلطّف الاعتراض.", "It softens the disagreement."]] },

  { id: "concerns", t: { ar: "تعبّر عن مخاوفك", en: "Expressing concerns" },
    body: { ar: "**I'm worried about…**، **My concern is that…**، **There's a risk that…**، و**What if…?**", en: "**I'm worried about…**, **My concern is that…**, **There's a risk that…**, and **What if…?**" },
    d: [["Julia", "Let's talk about the timeline. Launch is in three weeks.", "يلا نتكلم عن الجدول. الإطلاق بعد تلات أسابيع."],
        ["Ahmed", "I'm worried about the testing time. We only have four days for it.", "أنا قلقان من وقت الاختبار. عندنا أربع أيام بس."],
        ["Julia", "What's your main concern?", "إيه أكبر قلق عندك؟"],
        ["Ahmed", "My concern is that we won't find the payment bugs in time.", "قلقي إننا مش هنلاقي bugs الدفع في الوقت."],
        ["Julia", "There's a risk, I agree. What if we freeze new features a week earlier?", "فيه خطر، موافقة. طب لو وقفنا الخواص الجديدة قبلها بأسبوع؟"],
        ["Ahmed", "That would help a lot.", "ده هيفرق كتير."]],
    ph: [["I'm worried about the testing time.", "أنا قلقان من وقت الاختبار."], ["My concern is that…", "قلقي إن…"], ["There's a risk that…", "فيه خطر إن…"], ["That would help a lot.", "ده هيفرق كتير."]],
    q: [["f", "I'm worried ___ the testing time.", "about", ["for", "of"], "worried about تركيبة ثابتة.", "«worried about» is fixed."],
        ["f", "My ___ is that we won't find the bugs.", "concern", ["concerned", "worry about"], "My concern is that = قلقي إن.", "«My concern is that» introduces the worry."],
        ["f", "That ___ help a lot.", "would", ["will be", "is"], "would للنتيجة المتخيّلة.", "«would» for an imagined result."],
        ["m", "أحمد قلقان من إيه؟", "What is Ahmed worried about?", ["Too little testing time", "The design", "The budget"], 0, "the testing time.", "Too little testing time."],
        ["m", "جوليا اقترحت إيه؟", "What does Julia propose?", ["Freeze new features a week earlier", "Delay launch a year", "Skip testing"], 0, "freeze new features a week earlier.", "A feature freeze a week earlier."]] },

  { id: "compare", t: { ar: "تقرر بناءً على مقارنات", en: "Decisions based on comparisons" },
    body: { ar: "المقارنة: **cheaper than, more reliable than, the most…, not as… as**، وبعدها القرار.", en: "Comparing: **cheaper than, more reliable than, the most…, not as… as**, then the decision." },
    d: [["Reem", "Let's compare the two monitoring tools.", "يلا نقارن أداتين الـ monitoring."],
        ["Tom", "Tool A is cheaper than Tool B, but it's not as easy to set up.", "الأداة A أرخص من B، بس مش سهلة في الإعداد زيها."],
        ["Reem", "Which one is more reliable?", "أنهي واحدة أكتر اعتمادية؟"],
        ["Tom", "B. It has the best uptime of all the tools we tested.", "B. عندها أحسن uptime من كل الأدوات اللي جربناها."],
        ["Reem", "Then B is the better choice for us. Reliability matters more than price.", "يبقى B الاختيار الأحسن لينا. الاعتمادية أهم من السعر."]],
    ph: [["A is cheaper than B.", "A أرخص من B."], ["It's not as easy as B.", "مش سهلة زي B."], ["the best uptime of all", "أحسن uptime فيهم كلهم"], ["Reliability matters more than price.", "الاعتمادية أهم من السعر."]],
    q: [["f", "Tool A is ___ than Tool B.", "cheaper", ["more cheap", "cheapest"], "صفة قصيرة + er + than.", "Short adjective + -er + than."],
        ["f", "It's not as easy ___ B.", "as", ["than", "like"], "not as … as.", "«not as … as»."],
        ["f", "B is ___ reliable than A.", "more", ["most", "much"], "صفة طويلة: more + صفة + than.", "Long adjective: more + adjective + than."],
        ["m", "اختاروا أنهي أداة؟", "Which tool do they choose?", ["B", "A", "Neither"], 0, "B is the better choice for us.", "«B is the better choice.»"],
        ["m", "the best بنستخدمها إمتى؟", "When do we use «the best»?", ["Comparing one with all the others", "Comparing two things", "Talking about the past"], 0, "التفضيل الأعلى بين مجموعة.", "The top of a group."]] },

  { id: "modals", t: { ar: "الأفعال الناقصة (must / have to / should / may)", en: "Using modal verbs" },
    body: { ar: "**must / have to** للإلزام، **don't have to** = مش لازم، **mustn't** = ممنوع، **should** للنصيحة، **may / might** للاحتمال.", en: "**must / have to** for obligation, **don't have to** = not necessary, **mustn't** = forbidden, **should** for advice, **may / might** for possibility." },
    d: [["Security", "Everyone must use two-factor authentication from Monday.", "كله لازم يستخدم التحقق بخطوتين من يوم الاتنين."],
        ["Leo", "Do we have to change our passwords too?", "لازم نغيّر الباسوردات كمان؟"],
        ["Security", "You don't have to, but you should if they are old.", "مش لازم، بس الأحسن لو قديمة."],
        ["Security", "And you mustn't share your token with anyone, not even IT.", "وممنوع تشارك الـ token بتاعك مع أي حد، ولا حتى الـ IT."],
        ["Leo", "What if I lose my phone?", "ولو موبايلي ضاع؟"],
        ["Security", "Call us right away. We might ask you to verify your identity.", "كلّمنا على طول. ممكن نطلب منك تأكيد هويتك."]],
    ph: [["Everyone must use two-factor authentication.", "كله لازم يستخدم التحقق بخطوتين."], ["You don't have to, but you should.", "مش لازم، بس الأحسن."], ["You mustn't share your token.", "ممنوع تشارك الـ token."], ["We might ask you to verify your identity.", "ممكن نطلب منك تأكيد هويتك."]],
    q: [["f", "You ___ share your token. It's forbidden.", "mustn't", ["don't have to", "might not"], "mustn't = ممنوع.", "«mustn't» = forbidden."],
        ["f", "You don't ___ to change it, but you should.", "have", ["must", "need"], "don't have to = مش لازم.", "«don't have to» = not necessary."],
        ["f", "We ___ ask you to verify your identity.", "might", ["must to", "should to"], "might = احتمال.", "«might» = possibility."],
        ["m", "الفرق بين mustn't و don't have to؟", "Difference between «mustn't» and «don't have to»?", ["mustn't = forbidden; don't have to = not necessary", "They mean the same", "Both mean «should»"], 0, "mustn't ممنوع، don't have to مش ضروري.", "Forbidden vs not necessary."],
        ["m", "يعمل إيه لو الموبايل ضاع؟", "What to do if the phone is lost?", ["Call security right away", "Share the token", "Wait a week"], 0, "Call us right away.", "«Call us right away.»"]] },

  { id: "manage-conv", t: { ar: "تدير محادثة أو اجتماع", en: "Managing a conversation" },
    body: { ar: "تبدأ وتوجّه وتقفل: **Let's pick up where we left off**، **Sorry to interrupt**، **Let's get back to…**، **To sum up…**.", en: "Open, steer and close: **Let's pick up where we left off**, **Sorry to interrupt**, **Let's get back to…**, **To sum up…**." },
    d: [["Sara", "OK, let's pick up where we left off yesterday: the search feature.", "تمام، يلا نكمّل من حيث وقفنا امبارح: خاصية البحث."],
        ["Karim", "Before that, can I add something about the budget?", "قبلها، أقدر أضيف حاجة عن الميزانية؟"],
        ["Sara", "Let's keep that for the end, if that's OK.", "خلّيها للآخر، لو مفيش مانع."],
        ["Adam", "Sorry to interrupt, but the client just emailed about search.", "آسف إني بقاطع، بس العميل لسه بعت إيميل عن البحث."],
        ["Sara", "Perfect timing. Let's get back to search, then.", "في وقته. يلا نرجع للبحث بقى."],
        ["Sara", "To sum up: Adam replies to the client, Karim brings the budget at the end.", "الخلاصة: آدم يرد على العميل، وكريم يجيب الميزانية في الآخر."]],
    ph: [["Let's pick up where we left off.", "يلا نكمّل من حيث وقفنا."], ["Sorry to interrupt, but…", "آسف إني بقاطع، بس…"], ["Let's get back to…", "يلا نرجع لـ…"], ["To sum up, …", "الخلاصة، …"]],
    q: [["f", "Let's pick up where we left ___.", "off", ["out", "away"], "left off = وقفنا.", "«where we left off» = where we stopped."],
        ["f", "Sorry to ___, but the client emailed.", "interrupt", ["interrupting", "stop you of"], "Sorry to + فعل.", "«Sorry to» + base verb."],
        ["f", "To ___ up: Adam replies to the client.", "sum", ["some", "summary"], "To sum up = الخلاصة.", "«To sum up» = in summary."],
        ["m", "سارة عملت إيه مع موضوع الميزانية؟", "What did Sara do with the budget topic?", ["Moved it to the end", "Refused it", "Started with it"], 0, "Let's keep that for the end.", "She kept it for the end."],
        ["m", "أنهي جملة بتقفل بيها الاجتماع؟", "Which phrase closes the meeting?", ["To sum up, …", "Sorry to interrupt", "Let's pick up where we left off"], 0, "To sum up بيلخّص في الآخر.", "«To sum up» summarizes at the end."]] },

  { id: "misunderstand", t: { ar: "توضّح سوء الفهم", en: "Clarifying misunderstandings" },
    body: { ar: "**What I meant was…**، **Just to make sure I understand, …**، **I think there's been a misunderstanding.**", en: "**What I meant was…**, **Just to make sure I understand, …**, **I think there's been a misunderstanding.**" },
    d: [["Client", "You said the app would be ready on the first. Today is the first!", "إنتوا قلتوا التطبيق هيبقى جاهز يوم واحد. النهارده واحد!"],
        ["Dev", "I think there's been a misunderstanding. What I meant was the test version.", "أعتقد فيه سوء فهم. اللي كنت أقصده النسخة التجريبية."],
        ["Client", "So the final version isn't ready?", "يعني النسخة النهائية مش جاهزة؟"],
        ["Dev", "Not yet. Just to make sure I understand: you need the final version for your event on the tenth?", "لسه. بس عشان أتأكد إني فاهم: محتاج النسخة النهائية لحدثك يوم عشرة؟"],
        ["Client", "Exactly.", "بالظبط."],
        ["Dev", "Then we'll deliver it on the eighth. I'll confirm in writing today.", "يبقى هنسلّمها يوم تمانية. هأكد ده كتابة النهارده."]],
    ph: [["I think there's been a misunderstanding.", "أعتقد فيه سوء فهم."], ["What I meant was…", "اللي كنت أقصده…"], ["Just to make sure I understand, …", "عشان أتأكد إني فاهم، …"], ["I'll confirm in writing.", "هأكد كتابة."]],
    q: [["f", "What I ___ was the test version.", "meant", ["mean it", "meaning"], "What I meant was = اللي كنت أقصده.", "«What I meant was» corrects a misunderstanding."],
        ["f", "Just to make ___ I understand…", "sure", ["certain of", "right"], "make sure = أتأكد.", "«make sure» = check."],
        ["f", "I think there's ___ a misunderstanding.", "been", ["be", "being"], "there has been → there's been.", "«there has been» → «there's been»."],
        ["m", "النسخة النهائية هتتسلم إمتى؟", "When will the final version be delivered?", ["On the eighth", "On the first", "On the tenth"], 0, "we'll deliver it on the eighth.", "On the eighth."],
        ["m", "ليه يأكد كتابة؟", "Why confirm in writing?", ["To avoid another misunderstanding", "Because it is the law", "To be polite only"], 0, "الكتابة بتمنع سوء الفهم يتكرر.", "Writing prevents another misunderstanding."]] },

  { id: "speculate", t: { ar: "التخمين والطلبات", en: "Speculation and requests" },
    body: { ar: "تخمين عن الماضي: **It must have been…**، **It might have been…**، **You should have…**، وطلبات مهذبة **Would you mind…?**", en: "Guessing about the past: **It must have been…**, **It might have been…**, **You should have…**, and polite requests **Would you mind…?**" },
    d: [["Malik", "The server went down at 3 a.m. What happened?", "السيرفر وقع الساعة 3 الفجر. حصل إيه؟"],
        ["Eva", "It must have been the backup job. It runs at three.", "أكيد كان الـ backup job. بيشتغل الساعة تلاتة."],
        ["Malik", "Or it might have been the new update.", "أو ممكن يكون التحديث الجديد."],
        ["Eva", "True. We should have tested the update at night too.", "صح. كان المفروض نختبر التحديث بالليل كمان."],
        ["Malik", "Would you mind checking the backup logs?", "تمانعي تبصّي على logs الـ backup؟"],
        ["Eva", "Not at all. I'll do it now.", "خالص. هعملها دلوقتي."]],
    ph: [["It must have been the backup job.", "أكيد كان الـ backup job."], ["It might have been the update.", "ممكن يكون التحديث."], ["We should have tested it.", "كان المفروض نختبره."], ["Would you mind checking the logs?", "تمانع تبص على الـ logs؟"]],
    q: [["f", "It ___ have been the backup job. I'm almost sure.", "must", ["might", "should"], "must have = تخمين قوي.", "«must have» = a strong guess."],
        ["f", "We should ___ tested it at night.", "have", ["has", "had"], "should have + التصريف التالت = كان المفروض.", "«should have» + past participle = a past mistake."],
        ["f", "Would you mind ___ the logs?", "checking", ["check", "to check"], "Would you mind + ing.", "«Would you mind» + -ing."],
        ["m", "الرد المؤدب بالموافقة على Would you mind…?", "A polite yes to «Would you mind…?» is:", ["Not at all.", "Yes, I mind.", "Of course I mind."], 0, "Not at all = خالص، مش مانع.", "«Not at all» = I don't mind."],
        ["m", "might have been بتعبّر عن إيه؟", "What does «might have been» express?", ["A possible past cause", "A certain fact", "A future plan"], 0, "احتمال في الماضي.", "A possibility about the past."]] },

  { id: "adverbials", t: { ar: "العبارات الظرفية", en: "Adverbial phrases" },
    body: { ar: "عبارات بتقول إزاي وإمتى وقد إيه: **in a few minutes, on a regular basis, as quickly as possible, at the moment**.", en: "Phrases that say how, when and how often: **in a few minutes, on a regular basis, as quickly as possible, at the moment**." },
    d: [["Lead", "Our daily stand-ups take too long. How can we improve them?", "الـ stand-ups بتاعتنا بتطوّل. نحسّنها إزاي؟"],
        ["Nour", "Each person should speak for two minutes at most.", "كل واحد يتكلم دقيقتين بالكتير."],
        ["Ali", "And we can discuss details after the meeting, in smaller groups.", "ونقدر نناقش التفاصيل بعد الاجتماع، في مجموعات أصغر."],
        ["Lead", "Good. At the moment we also start late on a regular basis.", "كويس. وحاليًا كمان بنبدأ متأخر بشكل منتظم."],
        ["Nour", "Let's start on time, even if someone is missing.", "يلا نبدأ في الميعاد، حتى لو حد مش موجود."],
        ["Lead", "Agreed. Let's try it for two weeks and see.", "اتفقنا. نجربها أسبوعين ونشوف."]],
    ph: [["for two minutes at most", "دقيقتين بالكتير"], ["after the meeting, in smaller groups", "بعد الاجتماع، في مجموعات أصغر"], ["on a regular basis", "بشكل منتظم"], ["Let's start on time.", "يلا نبدأ في الميعاد."]],
    q: [["f", "Each person speaks for two minutes ___ most.", "at", ["in", "on"], "at most = بالكتير.", "«at most» = no more than."],
        ["f", "We start late on a regular ___.", "basis", ["base", "way"], "on a regular basis = بانتظام.", "«on a regular basis» = regularly."],
        ["f", "Let's start ___ time.", "on", ["in", "at"], "on time = في الميعاد بالظبط.", "«on time» = punctually."],
        ["m", "هيعملوا إيه في التفاصيل؟", "What happens to the details?", ["Discussed after the meeting in smaller groups", "Ignored", "Discussed first"], 0, "after the meeting, in smaller groups.", "After the meeting, in small groups."],
        ["m", "at the moment معناها إيه؟", "What does «at the moment» mean?", ["Now / currently", "In one minute", "Never"], 0, "at the moment = حاليًا.", "It means currently."]] },

  { id: "adjectives", t: { ar: "الصفات في الكلام", en: "Using adjectives in conversations" },
    body: { ar: "صفات دقيقة بدل good وbad: **reliable, outdated, urgent, affordable**، وترتيبها، و**-ed / -ing** (bored / boring).", en: "Precise adjectives instead of good and bad: **reliable, outdated, urgent, affordable**, their order, and **-ed / -ing** (bored / boring)." },
    d: [["Buyer", "We need new laptops for the support team. The current ones are outdated.", "محتاجين لابتوبات جديدة لفريق الدعم. اللي معانا قديمة."],
        ["IT", "How urgent is it?", "قد إيه مستعجل؟"],
        ["Buyer", "Quite urgent. People are frustrated, and the startup time is really annoying.", "مستعجل جدًا. الناس متضايقة، ووقت التشغيل مزعج فعلًا."],
        ["IT", "I can offer a lightweight, affordable model. It's reliable, too.", "أقدر أعرض موديل خفيف وسعره معقول. وكمان معتمد عليه."],
        ["Buyer", "Sounds suitable. Can you send a detailed quote?", "شكله مناسب. ممكن تبعت عرض سعر مفصّل؟"]],
    ph: [["The current ones are outdated.", "اللي معانا قديمة."], ["How urgent is it?", "قد إيه مستعجل؟"], ["A lightweight, affordable model", "موديل خفيف وسعره معقول"], ["Can you send a detailed quote?", "ممكن تبعت عرض سعر مفصّل؟"]],
    q: [["f", "People are ___ because the laptops are slow.", "frustrated", ["frustrating", "frustrate"], "-ed للإحساس بتاع الشخص.", "«-ed» describes how a person feels."],
        ["f", "The startup time is really ___.", "annoying", ["annoyed", "annoy"], "-ing للحاجة اللي بتسبب الإحساس.", "«-ing» describes the thing causing the feeling."],
        ["f", "Can you send a ___ quote?", "detailed", ["detail", "detailing"], "detailed = مفصّل.", "«detailed» = with many details."],
        ["m", "outdated معناها إيه؟", "What does «outdated» mean?", ["Old, no longer modern", "Very expensive", "Broken"], 0, "outdated = قديم ومش مواكب.", "No longer current."],
        ["m", "affordable معناها إيه؟", "What does «affordable» mean?", ["Not too expensive", "Very fast", "Heavy"], 0, "affordable = سعره معقول.", "Reasonably priced."]] },

  { id: "articles", t: { ar: "أدوات التحديد والـ articles", en: "Determiners and articles" },
    body: { ar: "**a / an / the / no article**، و**some / any / much / many / a few / a little / each / every**.", en: "**a / an / the / no article**, and **some / any / much / many / a few / a little / each / every**." },
    d: [["Kim", "We need a cloud storage solution for the backups.", "محتاجين حل تخزين سحابي للـ backups."],
        ["Rami", "How much data do we have?", "عندنا بيانات قد إيه؟"],
        ["Kim", "About two terabytes, and a few new gigabytes every day.", "حوالي 2 تيرا، وشوية جيجات جديدة كل يوم."],
        ["Rami", "Then the provider we use for the website is an option. They have an archive tier.", "يبقى الشركة اللي بنستخدمها للموقع اختيار. عندهم فئة أرشيف."],
        ["Kim", "Are there any limits on downloads?", "فيه أي حدود على التنزيل؟"],
        ["Rami", "Each download costs a little, but there are no limits.", "كل تنزيل بيتحسب بمبلغ صغير، بس مفيش حدود."]],
    ph: [["How much data do we have?", "عندنا بيانات قد إيه؟"], ["a few new gigabytes every day", "شوية جيجات جديدة كل يوم"], ["Are there any limits?", "فيه أي حدود؟"], ["Each download costs a little.", "كل تنزيل بيتحسب بمبلغ صغير."]],
    q: [["f", "How ___ data do we have?", "much", ["many", "few"], "data هنا اسم مايتعدّش → much.", "«data» is uncountable here → «much»."],
        ["f", "They have ___ archive tier.", "an", ["a", "the a"], "an قبل صوت متحرك (archive).", "«an» before a vowel sound."],
        ["f", "Are there ___ limits?", "any", ["some", "much"], "any في السؤال والنفي.", "«any» in questions and negatives."],
        ["m", "ليه the provider مش a provider؟", "Why «the provider», not «a provider»?", ["It's a specific one they already use.", "It's the first time they mention it.", "It's plural."], 0, "the لحاجة معروفة ومحددة.", "«the» = a specific, known one."],
        ["m", "a few بتيجي مع إيه؟", "What does «a few» go with?", ["Countable plural nouns", "Uncountable nouns", "Verbs"], 0, "a few gigabytes (بتتعد). a little money (ماتتعدش).", "Countable plurals (a few gigabytes)."]] },

  { id: "reported", t: { ar: "الكلام المنقول", en: "Reported speech" },
    body: { ar: "تنقل كلام غيرك: **He said (that) …**، والزمن بيرجع خطوة: is → was، will → would. **She asked if…**", en: "Report what others said: **He said (that) …**, and the tense moves back: is → was, will → would. **She asked if…**" },
    d: [["Manager", "What did the security team say about the incident?", "فريق الأمان قال إيه عن الحادثة؟"],
        ["Hadi", "They said that someone had used an old password.", "قالوا إن حد استخدم باسورد قديم."],
        ["Manager", "Did they say how many accounts were affected?", "قالوا كام حساب اتأثر؟"],
        ["Hadi", "Yes. Bella told me that only three accounts were affected.", "أيوه. بيلا قالتلي إن تلات حسابات بس اتأثروا."],
        ["Manager", "And what's next?", "وإيه الخطوة الجاية؟"],
        ["Hadi", "She said they would reset all passwords tonight, and she asked if we could tell the users.", "قالت إنهم هيعملوا reset لكل الباسوردات الليلة، وسألت لو نقدر نبلّغ المستخدمين."]],
    ph: [["They said that someone had used an old password.", "قالوا إن حد استخدم باسورد قديم."], ["She told me that…", "قالتلي إن…"], ["She said they would reset all passwords.", "قالت إنهم هيعملوا reset لكل الباسوردات."], ["She asked if we could tell the users.", "سألت لو نقدر نبلّغ المستخدمين."]],
    q: [["f", "«We will reset them.» → She said they ___ reset them.", "would", ["will", "are"], "will في الكلام المنقول بتبقى would.", "«will» becomes «would» in reported speech."],
        ["f", "Bella ___ me that three accounts were affected.", "told", ["said", "talked"], "told + شخص. said من غير شخص (أو said to).", "«told» + person; «said» without one."],
        ["f", "She asked ___ we could tell the users.", "if", ["that", "what"], "سؤال نعم/لا منقول → if.", "A reported yes/no question uses «if»."],
        ["m", "كام حساب اتأثر؟", "How many accounts were affected?", ["Three", "Thirty", "All of them"], 0, "only three accounts were affected.", "Three."],
        ["m", "«The build is broken.» بالكلام المنقول؟", "Report: «The build is broken.»", ["He said the build was broken.", "He said the build is break.", "He told the build was broken."], 0, "is → was، وsaid من غير مفعول.", "«is» → «was», and «said» with no object."]] },

  { id: "prepositions", t: { ar: "حروف الجر حسب السياق", en: "Prepositions in context" },
    body: { ar: "**in / on / at** للمكان والوقت، و**between, opposite, next to**، وتركيبات زي **depend on, responsible for**.", en: "**in / on / at** for place and time, **between, opposite, next to**, and combinations like **depend on, responsible for**." },
    d: [["Rana", "We're moving to the new office on the first of March.", "هننقل للمكتب الجديد يوم واحد مارس."],
        ["Leo", "Where is it exactly?", "فين بالظبط؟"],
        ["Rana", "On the fifth floor of the tower opposite the station, between the bank and a café.", "في الدور الخامس في البرج اللي قدام المحطة، بين البنك وكافيه."],
        ["Leo", "Will we sit in the same team areas?", "هنقعد في نفس أماكن الفرق؟"],
        ["Rana", "Mostly. The dev team will be next to the meeting rooms.", "غالبًا. فريق البرمجة هيبقى جنب أوض الاجتماعات."],
        ["Leo", "And the move itself? When does it start?", "والنقل نفسه؟ بيبدأ إمتى؟"],
        ["Rana", "At 8 a.m. It depends on the movers, but it should be done in one day.", "الساعة 8 الصبح. على حسب شركة النقل، بس المفروض يخلص في يوم."]],
    ph: [["on the first of March", "يوم واحد مارس"], ["on the fifth floor", "في الدور الخامس"], ["opposite the station", "قدام المحطة"], ["between the bank and a café", "بين البنك وكافيه"]],
    q: [["f", "We're moving ___ the first of March.", "on", ["in", "at"], "on مع التواريخ والأيام.", "«on» with dates and days."],
        ["f", "The office is ___ the fifth floor.", "on", ["in", "at"], "on the … floor.", "«on the … floor»."],
        ["f", "It starts ___ 8 a.m.", "at", ["on", "in"], "at مع الساعة.", "«at» with clock times."],
        ["m", "opposite the station معناها إيه؟", "What does «opposite the station» mean?", ["Facing the station across the street", "Inside the station", "Far from the station"], 0, "opposite = قصاد / قدام.", "Facing it, on the other side."],
        ["m", "فريق البرمجة هيقعد فين؟", "Where will the dev team sit?", ["Next to the meeting rooms", "On the roof", "In the café"], 0, "next to the meeting rooms.", "Next to the meeting rooms."]] },

  { id: "numbers", t: { ar: "تتكلم عن الأرقام مع زميل", en: "Talking about numbers with a coworker" },
    body: { ar: "تقرا الأرقام والنسب والتواريخ صح: **two point five, fifteen percent, a third, increase by, roughly**.", en: "Say numbers, percentages and dates correctly: **two point five, fifteen percent, a third, increase by, roughly**." },
    d: [["Sofia", "Let's plan the milestones. How many users do we have now?", "يلا نخطط للمراحل. عندنا كام مستخدم دلوقتي؟"],
        ["Tom", "Roughly twelve thousand five hundred.", "حوالي اتناشر ألف وخمسمية."],
        ["Sofia", "And growth?", "والنمو؟"],
        ["Tom", "It increased by fifteen percent last quarter. About a third came from the mobile app.", "زاد 15% الربع اللي فات. حوالي التلت جه من تطبيق الموبايل."],
        ["Sofia", "The page loads in two point five seconds. Our target is under one second.", "الصفحة بتحمل في 2.5 ثانية. هدفنا أقل من ثانية."],
        ["Tom", "Then milestone one, by June the thirtieth: cut load time by half.", "يبقى المرحلة الأولى، قبل 30 يونيو: نقلّل وقت التحميل للنص."]],
    ph: [["Roughly twelve thousand five hundred", "حوالي 12,500"], ["It increased by fifteen percent.", "زاد 15%."], ["about a third", "حوالي التلت"], ["two point five seconds", "2.5 ثانية"]],
    q: [["f", "It increased ___ fifteen percent.", "by", ["of", "with"], "increase by + المقدار.", "«increase by» + the amount."],
        ["f", "2.5 is read «two ___ five».", "point", ["comma", "dot and"], "العلامة العشرية بتتقرا point.", "The decimal mark is read «point»."],
        ["f", "___ twelve thousand users. (not exact)", "Roughly", ["Rough", "Exactly"], "roughly = تقريبًا.", "«roughly» = approximately."],
        ["m", "a third يعني قد إيه؟", "How much is «a third»?", ["1/3", "3", "30%"], 0, "a third = تلت.", "One of three equal parts."],
        ["m", "المرحلة الأولى هدفها إيه؟", "What is milestone one?", ["Cut load time by half by June 30", "Get 15% more users", "Launch the app"], 0, "cut load time by half.", "Halve the load time by June 30."]] },

  { id: "phrasal", t: { ar: "Phrasal verbs وتعبيرات مشهورة في الشغل", en: "Common phrasal verbs and idioms" },
    body: { ar: "**set up, look into, carry out, run out of, put off, catch up, on the same page, a heads-up, touch base**.", en: "**set up, look into, carry out, run out of, put off, catch up, on the same page, a heads-up, touch base**." },
    d: [["HR", "Thanks for joining. We're reviewing our remote-work policy.", "شكرًا إنكم جيتوا. بنراجع سياسة الشغل عن بعد."],
        ["Lead", "Good. Can you give us a heads-up before any change?", "كويس. ممكن تدّونا خبر قبل أي تغيير؟"],
        ["HR", "Of course. We'll carry out a short survey first, and then set up a meeting.", "أكيد. هنعمل استبيان قصير الأول، وبعدين نرتّب اجتماع."],
        ["Lead", "Some people ran out of vacation days. Will you look into that?", "فيه ناس خلصت أيام إجازتها. هتبصّوا على الموضوع ده؟"],
        ["HR", "Yes. Let's not put it off. I'll touch base with you on Thursday so we're all on the same page.", "أيوه. مانأجلوش. هتواصل معاك الخميس عشان نكون كلنا فاهمين نفس الحاجة."]],
    ph: [["Can you give us a heads-up?", "ممكن تدّونا خبر قبلها؟"], ["We'll set up a meeting.", "هنرتّب اجتماع."], ["Will you look into that?", "هتبص على الموضوع ده؟"], ["so we're all on the same page", "عشان نكون كلنا فاهمين نفس الحاجة"]],
    q: [["f", "We'll ___ up a meeting.", "set", ["put", "make"], "set up = يرتّب / يجهّز.", "«set up» = arrange."],
        ["f", "Some people ran ___ of vacation days.", "out", ["away", "off"], "run out of = خلص منه.", "«run out of» = have none left."],
        ["f", "Let's not put it ___.", "off", ["out", "on"], "put off = يأجّل.", "«put off» = postpone."],
        ["m", "a heads-up معناها إيه؟", "What is «a heads-up»?", ["An early warning or notice", "A promotion", "A meeting room"], 0, "a heads-up = تنبيه مسبق.", "Advance notice."],
        ["m", "on the same page معناها إيه؟", "What does «on the same page» mean?", ["Everyone understands the same thing", "Reading one book", "Working late"], 0, "متفقين وفاهمين نفس الحاجة.", "Sharing the same understanding."]] }
]});
